private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int index = i;
    while (bb.hasRemaining()) {
        byte b = bb.get();
        if (b >= 0) {
            sb.append((char) b);
        } else {
            // Handle multi-byte UTF-8 characters
            int numBytes = getNumBytes(b);
            if (!bb.hasRemaining(numBytes - 1)) {
                // Not enough remaining bytes for this character
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            char c = (char) decodeChar(b, bb);
            sb.append(c);
            numBytes--;
            while (numBytes > 0) {
                sb.append((char) bb.get());
                numBytes--;
            }
        }
        index++;
    }
    return index;
}

private static int getNumBytes(byte b) {
    if (b >= 0) {
        return 1;
    } else if ((b & 0xE0) == 0xC0) {
        return 2;
    } else if ((b & 0xF0) == 0xE0) {
        return 3;
    } else if ((b & 0xF8) == 0xF0) {
        return 4;
    } else {
        throw new IllegalArgumentException("Invalid UTF-8 leading byte");
    }
}

private static int decodeChar(byte first, ByteBuffer bb) {
    if ((first & 0xE0) == 0xC0) {
        // 2-byte UTF-8
        byte b1 = bb.get();
        return ((first & 0x1F) << 6) | (b1 & 0x3F);
    } else if ((first & 0xF0) == 0xE0) {
        // 3-byte UTF-8
        byte b1 = bb.get();
        byte b2 = bb.get();
        return ((first & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
    } else if ((first & 0xF8) == 0xF0) {
        // 4-byte UTF-8
        byte b1 = bb.get();
        byte b2 = bb.get();
        byte b3 = bb.get();
        return ((first & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
    } else {
        throw new IllegalArgumentException("Invalid UTF-8 sequence");
    }
}
