public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message using the provided schema and buffer
    byte[] data = schema.toByteArray(message, buffer);

    // Get the length of the serialized message
    int size = data.length;

    // Write the length of the message as a 32-bit integer in network byte order
    out.write((size >>> 24) & 0xFF);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);

    // Write the serialized message to the output stream
    out.write(data);

    // Return the size of the message
    return size;
}
