public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedTypes = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type actualTypeArgument = actualTypeArguments[i];
        Class<?> resolvedType = (actualTypeArgument instanceof Class<?>) ? (Class<?>) actualTypeArgument : null;
        if (resolvedType == null && targetType != null) {
            // Attempt resolution using targetType's type variables
            Type[] typeParameters = targetType.getTypeParameters();
            for (int j = 0; j < typeParameters.length; j++) {
                if (typeParameters[j].equals(actualTypeArgument)) {
                    resolvedType = targetType.getGenericSuperclass();
                    if (resolvedType instanceof ParameterizedType) {
                        ParameterizedType resolvedParameterizedType = (ParameterizedType) resolvedType;
                        resolvedType = (Class<?>) resolvedParameterizedType.getActualTypeArguments()[j];
                    }
                    break;
                }
            }
        }
        resolvedTypes[i] = resolvedType;
    }
    return resolvedTypes;
}
