protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = FETCH_DATA_DURATION; // Assuming FETCH_DATA_DURATION is a predefined constant

    if (end - start < fetchDataDuration) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long multiple = (end - start) / fetchDataDuration;
        long remainder = (end - start) % fetchDataDuration;

        for (long i = 0; i < multiple; i++) {
            long startTime = start + i * fetchDataDuration;
            long endTime = startTime + fetchDataDuration;
            timeRanges.add(new TimeRange(startTime, endTime));
        }

        if (remainder > 0) {
            long lastStartTime = start + multiple * fetchDataDuration;
            long lastEndTime = lastStartTime + remainder;
            timeRanges.add(new TimeRange(lastStartTime, lastEndTime));
        }
    }

    return timeRanges;
}

