static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;

    if (dayStep == 1) {
        return timeBucket;
    } else if (dayStep == 7) {
        if (day >= 1 && day <= 3) {
            day = 1;
        } else if (day >= 4 && day <= 10) {
            day = 8;
        } else if (day >= 11 && day <= 17) {
            day = 15;
        } else if (day >= 18 && day <= 24) {
            day = 22;
        } else {
            day = 30;
        }
    } else if (dayStep == 30) {
        if (day <= 5) {
            day = 1;
        } else if (day <= 15) {
            day = 11;
        } else {
            day = 26;
        }
    } else {
