    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    if (dayStep == 1) {
        day = day;
    } else if (dayStep % 7 == 0) {
        day += (7 - day % 7);
        if (day >= 32) {
            month++;
            day -= 31;
            if (month > 12) {
                month = 1;
                year++;
            }
        }
    } else {
        day += dayStep - (day - 1) % dayStep;
        if (day >= 32) {
            month++;
            day -= 31;
            if (month > 12) {
                month = 1;
                year++;
            }
        }
    }

    return year * 10000 + month * 100 + day;
