        int length = bytes.length;
        if (length > lb.getCapacity()) {
            lb = LinkedBuffer.expand(lb, length);
        }
        System.arraycopy(bytes, 0, lb.getData(), lb.getOffset(), length);
        lb.setOffset(lb.getOffset() + length);
