private static String substVars(String value, Properties props) {
    StringBuilder sb = new StringBuilder();
    int startIndex = 0;
    while (startIndex < value.length()) {
        int leftBrace = value.indexOf('${', startIndex);
        if (leftBrace == -1) {
            sb.append(value.substring(startIndex));
            break;
        }
        sb.append(value.substring(startIndex, leftBrace));
        int rightBrace = value.indexOf('}', leftBrace);
        if (rightBrace == -1) {
            sb.append(value.substring(leftBrace));
            break;
        }
        String varName = value.substring(leftBrace + 2, rightBrace);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            sb.append(varValue);
        } else {
            sb.append("${").append(varName).append("}");
        }
        startIndex = rightBrace + 1;
    }
    return sb.toString();
}
