public class PathDecoder {

    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        try {
            Path path = Paths.get(u);
            String[] parts = path.subpath(0, path.getNameCount()).toString().split("/");
            for (String part : parts) {
                if (!part.isEmpty()) {
                    if (decode) {
                        // Decode the part if the decode boolean is true
                        part = URI.create("?" + part).getQuery().substring(1);
                    }
                    pathSegments.add(new PathSegmentImpl(part));
                }
            }
        } catch (URISyntaxException e) {
            // Handle the exception as appropriate (e.g., log it, throw a custom exception, etc.)
            e.printStackTrace();
        }
        return pathSegments;
    }
}

