  int shift = 7;

  while ((firstByte & 0x80) != 0) {
    firstByte = inputStream.read();
    if (firstByte < 0) {
      throw new IOException("EOF while reading varint");
    }
    value |= (long) (firstByte & 0x7F) << shift;
    shift += 7;
    if (shift >= 64) {
      throw new IOException("Malformed varint");
    }
  }

