public static String trimTrailingWhitespace(String str) {
    if (str == null || str.isEmpty()) {
        return str;
    }
    int len = str.length();
    int st = len;
    while (st > 0 && Character.isWhitespace(str.charAt(st - 1))) {
        st--;
    }
    return str.substring(0, st);
}

