public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    boolean nextIsEscape = false;
    for (char ch : str.toCharArray()) {
        if (nextIsEscape) {
            switch (ch) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    sb.append('\\').append(ch);
                    break;
            }
            nextIsEscape = false;
        } else if (ch == '\\') {
            nextIsEscape = true;
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

