protected int removeUnusedNodes() {
    // Step 1: Check if the root node is null, if so, return 0
    if (root == null) {
        return 0;
    }

    // Step 2: Initialize a counter for inactive nodes
    int inactiveNodesCount = 0;

    // Step 3: Recursively remove inactive nodes starting from the root
    inactiveNodesCount += removeUnusedNodesHelper(root);

    // Step 4: Return the total count of inactive nodes removed
    return inactiveNodesCount;
}

private int removeUnusedNodesHelper(Category node) {
    if (node == null) {
        return 0;
    }

    int inactiveNodesCount = 0;

    // Recursively check and remove unused nodes in the current node's children
    for (Category child : node.getChildren()) {
        inactiveNodesCount += removeUnusedNodesHelper(child);
    }

    // If the current node is inactive, mark it for deletion and add to count
    if (!node.isActive()) {
        inactiveNodesCount++;
        node.markForDeletion();
    }

    // Optionally, clean up or update the node as necessary
    node.cleanup();

    return inactiveNodesCount;
}
