protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }

    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    Iterator<E> iterator = tour.iterator();
    V startVertex = graph.getEdgeSource(iterator.next());
    List<E> edges = new ArrayList<>();
    edges.add(iterator.next());

    while (iterator.hasNext()) {
        E edge = iterator.next();
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (source.equals(startVertex)) {
            edges.add(edge);
            startVertex = target;
        } else if (target.equals(startVertex)) {
            edges.add(graph.getEdge(source, target));
            startVertex = source;
        } else {
            throw new IllegalArgumentException("Tour contains edges that do not form a path");
        }
    }

    edges.add(graph.getEdge(startVertex, graph.getEdgeSource(edges.get(0))));
    return new GraphWalk<>(graph, startVertex, edges);
}
