private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel < 0 || minLabel >= bucketsByLabel.size() || bucketsByLabel.get(minLabel).isEmpty()) {
        return; // No need to reload if the bucket is out of bounds or already empty
    }

    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    for (int vertex : minBucket) {
        labels.set(vertex, 0); // Update the label of the vertex to 0
    }
    bucketsByLabel.set(0, bucketsByLabel.get(0).union(minBucket)); // Add vertices from minLabel bucket to bucket 0
    bucketsByLabel.set(minLabel, Collections.emptySet()); // Clear the minLabel bucket
