private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<V,E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.edges()) {
        List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();

        for (Vertex<V> neighbor : graph.neighbors(edge.source())) {
            if (!neighbor.equals(edge.target())) {
                Set<Integer> separator = findMinimalSeparator(graph, edge.source(), edge.target(), neighbor);
                localSeparatorList.addAll(separator.stream()
                        .map(v -> Pair.with(v, neighbor.id()))
                        .collect(Collectors.toList()));
            }
        }

        globalSeparatorList.add(Pair.with(localSeparatorList, edge));
    }

    return globalSeparatorList;
}

private Set<Integer> findMinimalSeparator(Graph<V,E> graph, V source, V target, V neighbor) {
    Set<Integer> separator = new HashSet<>();
    Queue<V> queue = new LinkedList<>();
    Set<V> visited = new HashSet<>();
    queue.add(neighbor);

    while (!queue.isEmpty()) {
        V current = queue.poll();
        if (!visited.contains(current)) {
            visited.add(current);
            for (V adj : graph.neighbors(current)) {
                if (!adj.equals(source) && !adj.equals(target) && !separator.contains(adj)) {
                    if (visited.contains(adj)) {
                        separator.add(adj);
                    } else {
                        queue.add(adj);
                    }
                }
            }
        }
    }

    // Remove source and target from the separator as they are not part of the actual separator
    separator.remove(source.id());
    separator.remove(target.id());

    return separator;
}
