import javax.swing.*;

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and pane cannot be null");
    }

    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Invalid row index");
    }

    // Select the specified row
    table.setRowSelectionInterval(row, row);

    // Get the visible rectangle of the selected row
    Rectangle rect = table.getCellRect(row, 0, true);

    // Scroll the JScrollPane to the newly selected row
    pane.getViewport().scrollRectToVisible(rect);

    // Delay repaint to ensure the table properly paints the newly selected row
    SwingUtilities.invokeLater(() -> {
        try {
            Thread.sleep(100); // Adjust the sleep time if necessary
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        table.repaint();
    });
}
