private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true; // An empty subgraph is trivially a clique
    }

    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.containsEdge(vertex1, vertex2)) {
                return false; // Found a non-edge, subgraph is not a clique
            }
        }
    }

    return true; // All pairs of vertices are connected by an edge
}
