public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true; // An empty graph or subgraph is trivially a clique
    }

    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue; // A vertex is not connected to itself
            }
            if (!graph.hasEdgeConnecting(v1, v2)) {
                return false; // The subgraph is not complete if there is no edge between v1 and v2
            }
        }
    }
    return true; // All vertices are connected, so the subgraph is a clique
}
